'use strict';

import { createError, MISSING_DOC } from 'pouchdb-errors';

import {MAIN_DOC_STORE} from './util';

export default function (txn, id, callback) {
  if (txn.error) {
    return callback(txn.error);
  }

  // TODO there looks like there should be optimisation here:
  // - local docs don't really have a meaningful rev_tree
  // - this function is only called internally, so perhaps there are
  //   guarantees it's only called on a doc that exists... if that's
  //   _not_ the case, then for local docs, it's currently an
  //   implicit check that the doc exists.
  const docStore = id.startsWith('_local/') ? LOCAL_DOC_STORE : MAIN_DOC_STORE;
  var req = txn.txn.objectStore(docStore).get(id);
  req.onsuccess = function (e) {
    if (!e.target.result) {
      callback(createError(MISSING_DOC));
    } else {
      callback(null, e.target.result.rev_tree);
    }
  };
}
